<?php
if ( php_sapi_name() !== 'cli' ) { exit; } // solo terminal, nunca via web
/**
 * HOMVUK - Arriendo de autos en el portal (hvkp-portal-autos)
 *
 *  1. El New MG ZS 2026 no aparecia en homvuk.com/Magnolio/: la seccion de
 *     arriendo trae la flota escrita a mano en la plantilla y quedo en 3 autos.
 *     Este snippet lo suma como primera tarjeta, tomando la foto y el precio
 *     del producto real, y corrige el contador de vehiculos.
 *  2. Le da preponderancia al arriendo: banner destacado encabezando el panel
 *     del huesped y la tarjeta de "Arriendo de Autos" primera y a todo el ancho.
 *
 * Todo vive en la base de datos (Code Snippets), sin archivos nuevos.
 *
 * Uso:  php hvkp-portal-autos.php            (aplicar)
 *       php hvkp-portal-autos.php restore    (desactivar)
 */

$HVKPA_B64  = '';
$HVKPA_MD5  = '9e7237d5481f611f170a5f4e6882051c';
$HVKPA_NAME = 'HOMVUK Portal Autos';

require __DIR__ . '/wp-load.php';
global $wpdb;

$tabla = $wpdb->prefix . 'snippets';
$mode  = isset( $argv[1] ) ? $argv[1] : 'aplicar';

if ( 'restore' === $mode ) {
    $wpdb->update( $tabla, array( 'active' => 0 ), array( 'name' => $HVKPA_NAME ) );
    if ( function_exists( 'wp_cache_flush' ) ) { wp_cache_flush(); }
    do_action( 'litespeed_purge_all' );
    echo "[OK]    Desactivado (el portal vuelve a como estaba)\n";
    exit( 0 );
}
if ( 'aplicar' !== $mode ) {
    echo "[ERROR] Argumento no reconocido: $mode. Usa 'aplicar' o 'restore'.\n";
    exit( 1 );
}

$code = base64_decode( $HVKPA_B64 );
if ( md5( $code ) !== $HVKPA_MD5 ) {
    echo "[ERROR] El contenido no paso la verificacion. Nada fue modificado.\n";
    exit( 1 );
}
if ( $wpdb->get_var( $wpdb->prepare( 'SHOW TABLES LIKE %s', $tabla ) ) !== $tabla ) {
    echo "[ERROR] No existe la tabla de snippets (plugin Code Snippets).\n";
    exit( 1 );
}

$fila = array(
    'name'        => $HVKPA_NAME,
    'description' => 'Suma el New MG ZS 2026 a la seccion de arriendo del portal y destaca el rent a car.',
    'code'        => $code,
    'tags'        => 'homvuk',
    'scope'       => 'front-end',
    'priority'    => 9,
    'active'      => 1,
    'modified'    => current_time( 'mysql' ),
);
$existe = $wpdb->get_var( $wpdb->prepare( "SELECT id FROM $tabla WHERE name = %s", $HVKPA_NAME ) );
if ( $existe ) {
    $wpdb->update( $tabla, $fila, array( 'id' => (int) $existe ) );
    echo "[OK]    Actualizado (id $existe)\n";
} else {
    $wpdb->insert( $tabla, $fila );
    echo "[OK]    Instalado (id " . $wpdb->insert_id . ")\n";
}

// Datos que va a mostrar, para revisarlos aca mismo
$zs = get_page_by_path( 'new-mg-zs-2026', OBJECT, 'product' );
if ( $zs ) {
    $usd = (float) get_post_meta( $zs->ID, '_price', true );
    $foto = get_the_post_thumbnail_url( $zs->ID, 'large' );
    echo "[OK]    New MG ZS 2026 encontrado (id {$zs->ID}) - USD " . ( $usd ? $usd : '129 (por defecto)' )
        . " = CLP " . number_format( round( ( $usd ? $usd : 129 ) * 816 ), 0, ',', '.' ) . "\n";
    echo "        Foto: " . ( $foto ? $foto : 'sin foto destacada' ) . "\n";
} else {
    echo "[AVISO] No se encontro el producto new-mg-zs-2026; la tarjeta usara los valores por defecto.\n";
}

if ( function_exists( 'wp_cache_flush' ) ) { wp_cache_flush(); }
do_action( 'litespeed_purge_all' );
if ( function_exists( 'rocket_clean_domain' ) ) { rocket_clean_domain(); }
echo "[OK]    Caches purgadas\n";

$res = wp_remote_get( home_url( '/Magnolio/?hvkpa=' . time() ), array( 'timeout' => 30, 'sslverify' => false ) );
if ( ! is_wp_error( $res ) ) {
    $body = (string) wp_remote_retrieve_body( $res );
    echo ( false !== strpos( $body, 'hvkpa-css' ) )
        ? "[OK]    Verificado: el portal ya carga los cambios\n"
        : "[AVISO] Aun no se ven en el portal (puede ser cache; revisar en unos minutos)\n";
}

echo "\n== HOMVUK - Arriendo de autos en el portal ==\n";
echo "Revisa https://homvuk.com/Magnolio/ y la seccion Arriendo de Autos.\n";
echo "Para volver atras: php hvkp-portal-autos.php restore\n";
